 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Emulator for the Bosch BMI160 accelerometer / gyro. This supports basic
 * init and reading of canned samples. It supports both I2C and SPI.
 *
 * Read data is handled by selecting the next sample value in test_data[] and
 * returning it to the caller.
 */

#include <zephyr/device.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/emul_sensor.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/drivers/spi.h>
#include <zephyr/drivers/spi_emul.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/byteorder.h>
#include <bmi160.h>

LOG_MODULE_DECLARE( BMI160, CONFIG_SENSOR_LOG_LEVEL);

#define NUM_REGS 0x80

struct bmi160_emul_data {
	/** Register values */
	uint8_t reg[NUM_REGS];
	/** Currently selected register */
	uint8_t cur_reg;
};

/** Static configuration for the emulator */
struct bmi160_emul_cfg {
	union {
		/** Unit address (I2C address or SPI CS) */
		uint16_t addr;
	};
	/** Pointer to runtime data */
	struct bmi160_emul_data *data;
};

/* Readings foreach register (wraps around after end) */
static const uint8_t test_data[] = {
	0x11, 0x22, 0x99, 0x05, 0x58, 0x45, 0x13, 0x23,
	0x69, 0x15, 0x55, 0x29, 0x91, 0x02, 0x11, 0xf2,
	0x99, 0x05,
	/* Repeated values for multiple reads */
	0x11, 0x22, 0x99, 0x05, 0x58, 0x45, 0x13, 0x23,
	0x69, 0x15, 0x55, 0x29, 0x91, 0x02, 0x11, 0xf2,
	0x99, 0x05,
};

uint8_t *emul_bmi160_get_reg_value(const struct emul *target, int reg_number, int count)
{
	struct bmi160_emul_data *data = target->data;

	if (reg_number < 0 || reg_number + count > NUM_REGS || count <= 0) {
		return NULL;
	}

	return data->reg + reg_number;
}

static void reg_write(const struct emul *target, int regn, int val)
{
	struct bmi160_emul_data *data = target->data;

	LOG_DBG("write %x = %x", regn, val);
	data->reg[regn] = val;
	switch (regn) {
	case BMI160_REG_ACC_CONF:
		break;
	case BMI160_REG_ACC_RANGE:
		break;
	case BMI160_REG_GYR_CONF:
		break;
	case BMI160_REG_GYR_RANGE:
		break;
	case BMI160_REG_CMD:
		switch (val) {
		case BMI160_CMD_SOFT_RESET:
			break;
		default:
			if ((val & BMI160_CMD_PMU_BIT) == BMI160_CMD_PMU_BIT) {
				int which = val & BMI160_CMD_PMU_MASK;
				int shift;
				int pmu_val = val & BMI160_CMD_PMU_VAL_MASK;

				switch (which) {
				case 0:
					shift = BMI160_PMU_STATUS_ACC_POS;
					break;
				case 1:
					shift = BMI160_PMU_STATUS_GYR_POS;
					break;
				case 2:
				default:
					shift = BMI160_PMU_STATUS_MAG_POS;
					break;
				}
				data->reg[BMI160_REG_PMU_STATUS] &= ~(3 << shift);
				data->reg[BMI160_REG_PMU_STATUS] |= pmu_val << shift;
			}
			break;
		}
		break;
	default:
		LOG_DBG("Unknown write %x", regn);
		break;
	}
}

static int reg_read(const struct emul *target, int regn)
{
	struct bmi160_emul_data *data = target->data;
	int val;

	val = data->reg[regn];
	LOG_DBG("read %x = %x", regn, val);

	return val;
}

#if DT_HAS_COMPAT_ON_BUS_STATUS_OKAY(bosch_bmi160, spi)
static int bmi160_emul_io_spi(const struct emul *target,
			      const struct spi_config *config,
			      const struct spi_buf_set *tx_bufs,
			      const struct spi_buf_set *rx_bufs)
{
	struct bmi160_emul_data *data;
	const struct spi_buf *tx, *txd, *rxd;
	unsigned int regn, val;
	int count;

	ARG_UNUSED(config);

	data = target->data;
	__ASSERT_NO_MSG(tx_bufs || rx_bufs);
	__ASSERT_NO_MSG(!tx_bufs || !rx_bufs ||
			tx_bufs->count == rx_bufs->count);
	count = tx_bufs ? tx_bufs->count : rx_bufs->count;
	if (count != 2) {
		LOG_DBG("Unknowntx_bufs->count %d", count);
		return -EIO;
	}
	tx = tx_bufs->buffers;
	txd = &tx_bufs->buffers[1];
	rxd = rx_bufs ? &rx_bufs->buffers[1] : NULL;

	switch (tx->len) {
	case 1:
		regn = *(uint8_t *)tx->buf;
		if ((regn & BMI160_REG_READ) && rxd == NULL) {
			LOG_ERR("Cannot read without rxd");
			return -EPERM;
		}
		switch (txd->len) {
		case 1:
			if (regn & BMI160_REG_READ) {
				regn &= BMI160_REG_MASK;
				val = reg_read(target, regn);
				*(uint8_t *)rxd->buf = val;
			} else {
				val = *(uint8_t *)txd->buf;
				reg_write(target, regn, val);
			}
			break;
		case BMI160_SAMPLE_SIZE:
			if (regn & BMI160_REG_READ) {
				regn &= BMI160_REG_MASK;
				for (int i = 0; i < BMI160_SAMPLE_SIZE; i++) {
					((uint8_t *)rxd->buf)[i] = reg_read(target, regn + i);
				}
			}
			break;
		default:
			LOG_DBG("Unknown sample size %zu", txd->len);
			return -EIO;
		}
		break;
	default:
		LOG_DBG("Unknown tx->len %d", tx->len);
		break;
	}

	return 0;
}
#endif

#if DT_HAS_COMPAT_ON_BUS_STATUS_OKAY(bosch_bmi160, i2c)
static int bmi160_emul_transfer_i2c(const struct emul *target,
				    struct i2c_msg *msgs, int num_msgs,
				    int addr)
{
	struct bmi160_emul_data *data;
	unsigned int val;

	data = target->data;

	__ASSERT_NO_MSG(msgs && num_msgs);

	i2c_dump_msgs_rw(target->dev, msgs, num_msgs, addr, false);
	switch (num_msgs) {
	case 2:
		if (msgs->flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected read");
			return -EIO;
		}
		if (msgs->len != 1) {
			LOG_ERR("Unexpected msg0 length %d", msgs->len);
			return -EIO;
		}
		data->cur_reg = msgs->buf[0];

		/* Now process the 'read' part of the message */
		msgs++;
		if (msgs->flags & I2C_MSG_READ) {
			switch (msgs->len) {
			case 1:
				val = reg_read(target, data->cur_reg);
				msgs->buf[0] = val;
				break;
			case BMI160_SAMPLE_SIZE:
				for (int i = 0; i < msgs->len; i++) {
					msgs->buf[i] = reg_read(target, data->cur_reg + i);
				}
				break;
			default:
				LOG_ERR("Unexpected read length %d", msgs->len);
				return -EIO;
			}
		} else {
			if (msgs->len != 1) {
				LOG_ERR("Unexpected msg1 length %d", msgs->len);
			}
			reg_write(target, data->cur_reg, msgs->buf[0]);
		}
		break;
	default:
		LOG_ERR("Invalid number of messages: %d", num_msgs);
		return -EIO;
	}

	return 0;
}
#endif

/* Device instantiation */

#if DT_HAS_COMPAT_ON_BUS_STATUS_OKAY(bosch_bmi160, spi)
static struct spi_emul_api bmi160_emul_api_spi = {
	.io = bmi160_emul_io_spi,
};
#endif

#if DT_HAS_COMPAT_ON_BUS_STATUS_OKAY(bosch_bmi160, i2c)
static struct i2c_emul_api bmi160_emul_api_i2c = {
	.transfer = bmi160_emul_transfer_i2c,
};
#endif

static int emul_bosch_bmi160_init(const struct emul *target, const struct device *parent)
{
	struct bmi160_emul_data *data = target->data;
	uint8_t *reg = data->reg;

	ARG_UNUSED(parent);

	reg[BMI160_REG_CHIPID] = BMI160_CHIP_ID;
	reg[BMI160_REG_PMU_STATUS] = 0;
	reg[BMI160_REG_STATUS] = BMI160_DATA_READY_BIT_MASK;
	for (size_t i = 0; i < ARRAY_SIZE(test_data); i++) {
		reg[BMI160_REG_DATA_MAG_X + i] = test_data[i];
	}

	return 0;
}

static int bmi160_emul_backend_set_channel(const struct emul *target, struct sensor_chan_spec ch,
					   const q31_t *value, int8_t shift)
{
	if (!target || !target->data) {
		return -EINVAL;
	}

	struct bmi160_emul_data *data = target->data;
	int64_t intermediate = (int64_t)*value << shift;
	int64_t reg_val;
	int32_t scale;
	uint8_t reg_lsb;

	switch (ch.chan_type) {
	case SENSOR_CHAN_ACCEL_X:
	case SENSOR_CHAN_ACCEL_Y:
	case SENSOR_CHAN_ACCEL_Z:
		switch (ch.chan_type) {
		case SENSOR_CHAN_ACCEL_X:
			reg_lsb = BMI160_REG_DATA_ACC_X;
			break;
		case SENSOR_CHAN_ACCEL_Y:
			reg_lsb = BMI160_REG_DATA_ACC_Y;
			break;
		case SENSOR_CHAN_ACCEL_Z:
			reg_lsb = BMI160_REG_DATA_ACC_Z;
			break;
		default:
			__ASSERT_UNREACHABLE;
		}

		switch (data->reg[BMI160_REG_ACC_RANGE]) {
		case BMI160_ACC_RANGE_2G:
			scale = 16384;
			break;
		case BMI160_ACC_RANGE_4G:
			scale = 8192;
			break;
		case BMI160_ACC_RANGE_8G:
			scale = 4096;
			break;
		case BMI160_ACC_RANGE_16G:
			scale = 2048;
			break;
		default:
			return -EINVAL;
		}

		reg_val = intermediate * scale / (SENSOR_G * (1LL << 31) / 1000000LL);
		break;
	case SENSOR_CHAN_GYRO_X:
	case SENSOR_CHAN_GYRO_Y:
	case SENSOR_CHAN_GYRO_Z:
		switch (ch.chan_type) {
		case SENSOR_CHAN_GYRO_X:
			reg_lsb = BMI160_REG_DATA_GYR_X;
			break;
		case SENSOR_CHAN_GYRO_Y:
			reg_lsb = BMI160_REG_DATA_GYR_Y;
			break;
		case SENSOR_CHAN_GYRO_Z:
			reg_lsb = BMI160_REG_DATA_GYR_Z;
			break;
		default:
			__ASSERT_UNREACHABLE;
		}

		switch (data->reg[BMI160_REG_GYR_RANGE]) {
		case BMI160_GYR_RANGE_2000DPS:
			scale = 164;
			break;
		case BMI160_GYR_RANGE_1000DPS:
			scale = 328;
			break;
		case BMI160_GYR_RANGE_500DPS:
			scale = 656;
			break;
		case BMI160_GYR_RANGE_250DPS:
			scale = 1312;
			break;
		case BMI160_GYR_RANGE_125DPS:
			scale = 2624;
			break;
		default:
			return -EINVAL;
		}

		reg_val = intermediate * scale * 180LL / (SENSOR_PI * 10LL * (1LL << 31) / 1000000LL);
		break;
	default:
		return -ENOTSUP;
	}

	sys_put_le16(CLAMP(reg_val, INT16_MIN, INT16_MAX), &data->reg[reg_lsb]);
	return 0;
}

static int bmi160_emul_backend_get_sample_range(const struct emul *target,
						struct sensor_chan_spec ch, q31_t *lower,
						q31_t *upper, q31_t *epsilon, int8_t *shift)
{
	if (!lower || !upper || !epsilon || !shift) {
		return -EINVAL;
	}

	struct bmi160_emul_data *data = target->data;

	switch (ch.chan_type) {
	case SENSOR_CHAN_ACCEL_X:
	case SENSOR_CHAN_ACCEL_Y:
	case SENSOR_CHAN_ACCEL_Z:
		switch (data->reg[BMI160_REG_ACC_RANGE]) {
		case BMI160_ACC_RANGE_2G:
			*shift = 5;
			*upper = (int64_t)(2 * SENSOR_G * (1LL << (31 - 5)) / 1000000LL);
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		case BMI160_ACC_RANGE_4G:
			*shift = 6;
			*upper = (int64_t)(4 * SENSOR_G * (1LL << (31 - 6)) / 1000000LL);
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		case BMI160_ACC_RANGE_8G:
			*shift = 7;
			*upper = (int64_t)(8 * SENSOR_G * (1LL << (31 - 7)) / 1000000LL);
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		case BMI160_ACC_RANGE_16G:
			*shift = 8;
			*upper = (int64_t)(16 * SENSOR_G * (1LL << (31 - 8)) / 1000000LL);
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		default:
			return -EINVAL;
		}
		return 0;
	case SENSOR_CHAN_GYRO_X:
	case SENSOR_CHAN_GYRO_Y:
	case SENSOR_CHAN_GYRO_Z:
		switch (data->reg[BMI160_REG_GYR_RANGE]) {
		case BMI160_GYR_RANGE_2000DPS:
			*shift = 6;
			*upper = (int64_t)(2000 * SENSOR_PI * (1LL << (31 - 6)) /
					   (180LL * 1000000LL));
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		case BMI160_GYR_RANGE_1000DPS:
			*shift = 5;
			*upper = (int64_t)(1000 * SENSOR_PI * (1LL << (31 - 5)) /
					   (180LL * 1000000LL));
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		case BMI160_GYR_RANGE_500DPS:
			*shift = 4;
			*upper = (int64_t)(500 * SENSOR_PI * (1LL << (31 - 4)) /
					   (180LL * 1000000LL));
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		case BMI160_GYR_RANGE_250DPS:
			*shift = 3;
			*upper = (int64_t)(250 * SENSOR_PI * (1LL << (31 - 3)) /
					   (180LL * 1000000LL));
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		case BMI160_GYR_RANGE_125DPS:
			*shift = 2;
			*upper = (int64_t)(125 * SENSOR_PI * (1LL << (31 - 2)) /
					   (180LL * 1000000LL));
			*lower = -*upper;
			*epsilon = *upper / 32768;
			break;
		default:
			return -EINVAL;
		}
		return 0;
	default:
		return -ENOTSUP;
	}
}

static const struct emul_sensor_driver_api bmi160_emul_sensor_driver_api = {
	.set_channel = bmi160_emul_backend_set_channel,
	.get_sample_range = bmi160_emul_backend_get_sample_range,
};

#define BMI160_EMUL_DATA(n) \
	static struct bmi160_emul_data bmi160_emul_data_##n;

#define BMI160_EMUL_DEFINE(n, bus_api) \
	EMUL_DT_INST_DEFINE(n, emul_bosch_bmi160_init, &bmi160_emul_data_##n, \
			    &bmi160_emul_cfg_##n, &bus_api, &bmi160_emul_sensor_driver_api)

/* Instantiation for each device on SPI */
#define BMI160_EMUL_SPI(n) \
	BMI160_EMUL_DATA(n) \
	static const struct bmi160_emul_cfg bmi160_emul_cfg_##n = { \
		.addr = DT_INST_REG_ADDR(n), \
		.data = &bmi160_emul_data_##n \
	}; \
	BMI160_EMUL_DEFINE(n, bmi160_emul_api_spi)

/* Instantiation for each device on I2C */
#define BMI160_EMUL_I2C(n) \
	BMI160_EMUL_DATA(n) \
	static const struct bmi160_emul_cfg bmi160_emul_cfg_##n = { \
		.addr = DT_INST_REG_ADDR(n), \
		.data = &bmi160_emul_data_##n \
	}; \
	BMI160_EMUL_DEFINE(n, bmi160_emul_api_i2c)

#define BMI160_EMUL(n) \
	COND_CODE_1(DT_INST_ON_BUS(n, spi), \
		    (BMI160_EMUL_SPI(n)), \
		    (BMI160_EMUL_I2C(n)))

DT_INST_FOREACH_STATUS_OKAY(BMI160_EMUL)
